)) {
// acquire an exclusive lock
ftruncate
(
$fp
,
0
);
// truncate file
rewind
(
$fp
);
fwrite
(
$fp
,
"Write something here\n"
);
fflush
(
$fp
);
// flush output before releasing the lock
flock
(
$fp
,
